def band_index(segs, x):
    """The index of the segment containing position x."""
    return next(k for k,(a,b) in enumerate(segs) if a<=x<=b)

def marker_spans_fill(grid, colors, border=8):
    """Grid of cells bounded by border lines: for each marker color, fill every cell between the extreme marker cells of each cell-row and cell-column with that color; crossings of two colors become their blend via blend_at; original markers and borders are kept."""
    H,W=len(grid),len(grid[0])
    R=border_segs(grid,border)
    C=border_segs([[grid[i][j] for i in range(H)] for j in range(W)],border)
    marks={}
    for i in range(H):
        for j in range(W):
            if grid[i][j] in colors: marks.setdefault(grid[i][j],[]).append((i,j))
    cov={c:set() for c in marks}
    for col,pts in marks.items():
        rows={}; cols_={}
        for (i,j) in pts:
            rows.setdefault(band_index(R,i),[]).append(band_index(C,j))
            cols_.setdefault(band_index(C,j),[]).append(band_index(R,i))
        for rb,cbs in rows.items():
            a,b=R[rb]
            for cb in range(min(cbs),max(cbs)+1):
                c,d=C[cb]
                for i in range(a,b+1):
                    for j in range(c,d+1): cov[col].add((i,j))
        for cb,rbs in cols_.items():
            c,d=C[cb]
            for rb in range(min(rbs),max(rbs)+1):
                a,b=R[rb]
                for i in range(a,b+1):
                    for j in range(c,d+1): cov[col].add((i,j))
    out=[[0]*W for _ in range(H)]
    order=list(marks)
    for i in range(H):
        for j in range(W):
            hit=[c for c in order if (i,j) in cov[c]]
            out[i][j]= blend_at(hit) if len(hit)>1 else (hit[0] if hit else 0)
    for i in range(H):
        for j in range(W):
            if grid[i][j] in colors or grid[i][j]==border: out[i][j]=grid[i][j]
    return out

def blend_at(colors):
    """The color where fills of several marker colors cross (2 and 3 mix to 6)."""
    m={frozenset((2,3)):6}
